<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,useId} from 'vue'
import {api,APIError,body,list,type Row} from '../api'
import {confirmAction} from '../confirm'
import {randomID} from '../random'
import SelectField from './SelectField.vue'
import Icon from './Icon.vue'

type Kind='steam'|'music'|'photos'
type Upload={id:string;file:File;key:string;state:'queued'|'uploading'|'failed'|'ready';media_id:string;preview:string;error:string;retryable:boolean}
const names:Record<string,string>={intro:'个人介绍',articles:'最近文章',steam:'游戏墙',music:'唱片墙',photos:'照片墙',closing:'结尾',activity:'更新频率',projects:'项目卡片'}
const kinds=[{value:'steam',label:'Steam 游戏'},{value:'music',label:'Apple Music 唱片'},{value:'photos',label:'个人照片'}]
const uid=useId(),view=ref('content'),section=ref('intro'),kind=ref<Kind>('steam'),busy=ref(''),ready=ref(false),loadingHome=ref(true),loadingItems=ref(false)
const config=ref<Row>({}),version=ref(0),roles=ref(''),steam=reactive({steam_id:'',mode:'owned',auto_sync_enabled:false}),steamStatus=ref<Row>({}),apiKey=ref(''),clearKey=ref(false)
const homeInitial=ref(''),homeError=ref(''),homeConflict=ref(false),message=ref(''),itemError=ref(''),listError=ref(''),importError=ref('')
const items=ref<Row[]>([]),page=ref(0),cursors=ref(['']),nextCursor=ref(''),item=reactive<Row>({}),itemInitial=ref(''),itemConflict=ref(false),importInput=ref(''),importPreview=ref<Row|null>(null)
const playlistStatus=ref<Row|null>(null),playlistPreview=ref<Row|null>(null),playlistInput=ref(''),playlistError=ref(''),playlistLoading=ref(false),playlistConflict=ref(false),playlistImportedID=ref(''),playlistExpired=ref(false)
const isPlaylist=computed(()=>{if(kind.value!=='music')return false;try{return /\/playlist\//.test(new URL(importInput.value.trim()).pathname)}catch{return false}})
const playlistInputChanged=computed(()=>!!playlistPreview.value&&importInput.value.trim()!==playlistInput.value)
const playlistDirty=computed(()=>!!playlistPreview.value&&playlistImportedID.value!==playlistPreview.value.preview_id)
const cover=ref<Upload|null>(null),photos=ref<Upload[]>([]),activePhoto=ref(''),fileInput=ref<HTMLInputElement>(),photoInput=ref<HTMLInputElement>(),maxBytes=ref(10485760)
const selectedSection=computed(()=>config.value.sections?.[section.value])
const uploading=computed(()=>cover.value?.state==='uploading'||photos.value.some(p=>p.state==='queued'||p.state==='uploading'))
const locked=computed(()=>!!busy.value||uploading.value)
const sizeLabel=computed(()=>`${Number((maxBytes.value/1048576).toFixed(1))} MiB`)
const count=(value:unknown)=>Array.from(String(value||'')).length
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const configValue=():Row=>({...clone(config.value),intro_roles:roles.value.split(/[、,，\n]/).map(s=>s.trim()).filter(Boolean)})
const steamValue=()=>({steam_id:steam.steam_id,mode:steam.mode,auto_sync_enabled:steam.auto_sync_enabled})
const homeSnapshot=()=>JSON.stringify({config:configValue(),steam:steamValue()})
const homeAttemptSnapshot=()=>JSON.stringify({home:homeSnapshot(),api_key:apiKey.value,clear_api_key:clearKey.value})
const homeDirty=computed(()=>ready.value&&(homeSnapshot()!==homeInitial.value||!!apiKey.value||clearKey.value))
function blankItem(value:Kind):Row{return {id:'',version:0,kind:value,title:'',subtitle:'',alt:'',url:'',image_url:'',hero_url:'',logo_url:'',playtime_minutes:null,media_id:'',provider_id:'',position:0,visible:false,source:'manual'}}
function itemValue(value:Row=item):Row{return {kind:value.kind,title:value.title,subtitle:value.subtitle,alt:value.alt,url:value.url,image_url:value.media_id?'':value.image_url,hero_url:value.kind==='steam'?value.hero_url:'',logo_url:value.kind==='steam'?value.logo_url:'',media_id:value.media_id,provider_id:value.provider_id,position:value.position,visible:value.visible}}
const itemSnapshot=()=>JSON.stringify(itemValue())
const itemDirty=computed(()=>itemSnapshot()!==itemInitial.value||!!cover.value)
const dirty=computed(()=>homeDirty.value||itemDirty.value||photos.value.length>0||uploading.value||playlistDirty.value||projectDirty.value)
function remotePreview(value:string){try{const url=new URL(value);return url.protocol==='https:'&&/(^|\.)(steamstatic\.com|steamcdn-a\.akamaihd\.net|steamusercontent\.com|mzstatic\.com)$/.test(url.hostname)?url.href:''}catch{return ''}}
const imageSource=computed(()=>cover.value?.preview||(item.media_id?'/media/'+item.media_id:remotePreview(item.image_url)))
const credentialsReady=computed(()=>!!steam.steam_id&&(!!apiKey.value||(!clearKey.value&&!!steamStatus.value.api_key_configured)))
let stopped=false,sequence=0,listController:AbortController|undefined,uploadController:AbortController|undefined,queueRunning=false
let itemKey=randomID(),syncKey=randomID(),pendingItem:{key:string;payload:Row}|null=null,pendingHome:{key:string;version:number;payload:Row;snapshot:string}|null=null
let pendingPlaylistPreview:{key:string;input:string;refresh:boolean}|null=null,pendingPlaylistImport:{key:string;version:number;preview_id:string}|null=null,playlistSequence=0

function parseHome(data:Row){
 const c=data?.config,s=data?.steam,keys=Object.keys(names)
 if(!Number.isSafeInteger(Number(data?.version))||Number(data.version)<1||!c||!s||!Array.isArray(c.order)||c.order.length!==keys.length||new Set(c.order).size!==keys.length||c.order.some((k:string)=>!keys.includes(k))||keys.some(k=>!c.sections?.[k]||typeof c.sections[k].enabled!=='boolean'||!Number.isSafeInteger(c.sections[k].limit)||['title','description','link_label','link_url'].some(f=>typeof c.sections[k][f]!=='string'))||!c.activity||!['posts_moments','posts','moments'].includes(c.activity.source)||!['rolling','year'].includes(c.activity.period)||typeof c.activity.timezone!=='string'||!Number.isInteger(c.activity.year)||!Array.isArray(c.intro_roles)||c.intro_roles.some((r:unknown)=>typeof r!=='string')||typeof c.use_site_intro!=='boolean'||typeof c.motion_enabled!=='boolean'||typeof c.warmth_enabled!=='boolean'||['intro_name','writing_title','writing_description','scroll_label'].some(k=>typeof c[k]!=='string')||typeof s.steam_id!=='string'||typeof s.auto_sync_enabled!=='boolean'||typeof s.api_key_configured!=='boolean'||!['owned','recent'].includes(s.mode))throw new Error('首页设置未完整载入，当前修改已保留。')
 return data
}
function applyHome(data:Row,preserve=false){
 parseHome(data);version.value=Number(data.version);steamStatus.value=clone(data.steam)
 homeInitial.value=JSON.stringify({config:clone(data.config),steam:{steam_id:data.steam.steam_id,mode:data.steam.mode,auto_sync_enabled:!!data.steam.auto_sync_enabled}})
 if(!preserve){config.value=clone(data.config);roles.value=data.config.intro_roles.join('、');Object.assign(steam,{steam_id:data.steam.steam_id,mode:data.steam.mode,auto_sync_enabled:!!data.steam.auto_sync_enabled});apiKey.value='';clearKey.value=false}
 const bytes=Number(data.max_image_bytes);if(Number.isSafeInteger(bytes)&&bytes>0)maxBytes.value=bytes
 ready.value=true;homeConflict.value=false
}
async function loadHome(replace=false){
 if(locked.value)return
 if(replace&&homeDirty.value&&!await confirmAction('载入服务器首页设置？','当前页面内容和 Steam 设置修改将被替换，展示墙条目输入会保留。','载入最新设置'))return
 loadingHome.value=true;busy.value='read-home';homeError.value=''
 try{const data=await api('/admin/home');if(!stopped){applyHome(data);pendingHome=null}}catch(e){homeError.value=(e as Error).message}finally{loadingHome.value=false;busy.value=''}
}
function homeProblem(){
 if(!ready.value)return '请先载入首页设置。'
 const c=configValue()
 if(!Number.isInteger(c.activity?.year)||(c.activity.year!==0&&(c.activity.year<2000||c.activity.year>2100)))return '统计年份请选择0（当前年份）或2000至2100之间的年份。'
 for(const key of c.order){const s=c.sections[key],label=names[key];if(count(s.title)>80||count(s.description)>600||count(s.link_label)>60||count(s.link_url)>2048)return label+'的文案或链接超出上限。';const max=key==='articles'?12:['steam','music','photos','projects'].includes(key)?24:0;if(!Number.isInteger(Number(s.limit))||Number(s.limit)<0||Number(s.limit)>max)return label+'的显示数量不正确。'}
 if(count(c.intro_name)>80||c.intro_roles.length>12||c.intro_roles.some((r:string)=>count(r)>60)||count(c.writing_title)>80||count(c.writing_description)>600||count(c.scroll_label)>60)return '介绍或滚动文案超出上限，请检查后保存。'
 if(steam.steam_id&&!/^\d{17}$/.test(steam.steam_id))return 'Steam ID64 须为17位数字。'
 if(steam.auto_sync_enabled&&!credentialsReady.value)return '自动同步需要先填写 Steam ID64 和 API Key。'
 return ''
}
async function saveHome(){
 if(locked.value||homeConflict.value||!homeDirty.value)return
 const problem=homeProblem();if(problem){homeError.value=problem;return}
 busy.value='save-home';homeError.value='';message.value=''
 try{
  pendingHome||={key:randomID(),version:version.value,snapshot:homeAttemptSnapshot(),payload:{config:configValue(),steam:{...steamValue(),...(apiKey.value?{api_key:apiKey.value}:{}),...(clearKey.value?{clear_api_key:true}:{})}}}
  const attempt=pendingHome,result=await api('/admin/home',{method:'PUT',version:attempt.version,key:attempt.key,body:body(attempt.payload)})
  if(stopped)return
  const preserve=homeAttemptSnapshot()!==attempt.snapshot;applyHome(result,preserve);pendingHome=null
  if(preserve){if(apiKey.value===attempt.payload.steam.api_key)apiKey.value='';if(attempt.payload.steam.clear_api_key)clearKey.value=false}
  message.value=preserve?'已确认上次保存。当前新修改仍未保存。':'首页设置已保存。'
 }catch(e){homeError.value=(e as Error).message;if(e instanceof APIError&&[409,412].includes(e.status)){homeConflict.value=true;pendingHome=null;homeError.value='首页设置已在其他位置更新，当前修改已保留。请确认后载入最新设置。'}else if(e instanceof APIError&&[400,422].includes(e.status))pendingHome=null}
 finally{busy.value=''}
}
async function moveSection(index:number|string,step:number){if(locked.value)return;const at=Number(index),order=config.value.order,target=at+step;if(target<0||target>=order.length)return;const [key]=order.splice(at,1);order.splice(target,0,key);await nextTick();document.getElementById(uid+'-section-'+key)?.focus()}
async function editSection(key:string){section.value=key;await nextTick();document.getElementById(uid+'-section-editor')?.focus()}
function tabKey(event:KeyboardEvent){const buttons=Array.from((event.currentTarget as HTMLElement).querySelectorAll<HTMLButtonElement>('[role=tab]')),at=buttons.indexOf(event.target as HTMLButtonElement);let to=at;if(event.key==='ArrowRight')to=(at+1)%buttons.length;else if(event.key==='ArrowLeft')to=(at-1+buttons.length)%buttons.length;else if(event.key==='Home')to=0;else if(event.key==='End')to=buttons.length-1;else return;event.preventDefault();buttons[to]?.click();buttons[to]?.focus()}
function parseItem(data:Row):Row{if(!data||!String(data.id||'')||!Number.isSafeInteger(Number(data.version))||Number(data.version)<1||!['steam','music','photos'].includes(data.kind)||['title','subtitle','alt','url','image_url','hero_url','logo_url','media_id','provider_id'].some(k=>typeof data[k]!=='string')||!(data.playtime_minutes===null||(Number.isSafeInteger(data.playtime_minutes)&&data.playtime_minutes>=0))||!Number.isSafeInteger(data.position)||typeof data.visible!=='boolean')throw new Error('条目数据不完整，当前输入已保留。');return {...blankItem(data.kind),...data,id:String(data.id),version:Number(data.version),image_url:data.media_id?'':data.image_url||''}}
function release(upload:Upload|null){if(upload?.preview){URL.revokeObjectURL(upload.preview);upload.preview=''}}
function resetCover(){release(cover.value);cover.value=null}
function fillItem(data?:Row,preserve=false){const local=clone(itemValue()),photo=activePhoto.value;if(!preserve)resetCover();Object.keys(item).forEach(k=>delete item[k]);Object.assign(item,data?parseItem(data):blankItem(kind.value));itemInitial.value=JSON.stringify(itemValue());if(preserve)Object.assign(item,local);itemConflict.value=false;if(!preserve){activePhoto.value='';itemKey=randomID();pendingItem=null}else activePhoto.value=photo}
fillItem()
async function loadItems(){
 const at=++sequence;listController?.abort();listController=new AbortController();loadingItems.value=true;listError.value='';items.value=[];nextCursor.value=''
 try{const q=new URLSearchParams({kind:kind.value,limit:'20'});if(cursors.value[page.value])q.set('cursor',cursors.value[page.value]);const data=await api('/admin/home/items?'+q,{signal:listController.signal});if(!stopped&&at===sequence){items.value=list(data).map(parseItem);nextCursor.value=data.has_more===false?'':data.next_cursor||data.cursor||''}}
 catch(e){if(at===sequence&&(e as Error).name!=='AbortError')listError.value=(e as Error).message}finally{if(at===sequence)loadingItems.value=false}
}
async function changeKind(value:string|number){
 if(locked.value)return
 if((itemDirty.value||photos.value.length||playlistDirty.value)&&!await confirmAction('切换展示墙？','当前未保存的条目、歌单预览和待核对照片会放弃，已保存内容不受影响。','切换展示墙'))return
 photos.value.forEach(release);photos.value=[];kind.value=value as Kind;fillItem();importInput.value='';importPreview.value=null;playlistPreview.value=null;playlistImportedID.value='';playlistInput.value='';playlistError.value='';playlistExpired.value=false;playlistConflict.value=false;pendingPlaylistPreview=null;pendingPlaylistImport=null;importError.value='';itemError.value='';page.value=0;cursors.value=[''];void loadItems();if(kind.value==='music')void loadPlaylistStatus()
}
function paginate(step:number){if(locked.value||loadingItems.value||(step<0&&!page.value)||(step>0&&!nextCursor.value))return;if(step>0)cursors.value[page.value+1]=nextCursor.value;page.value+=step;void loadItems()}
async function editItem(row?:Row){if(locked.value)return;if(itemDirty.value&&!await confirmAction('放弃未保存的条目？','当前标题、图片和其他修改将被替换。','放弃修改'))return;fillItem(row);itemError.value='';message.value='';await nextTick();document.getElementById(uid+'-item-title')?.focus()}
function itemProblem(){if(!item.title.trim()||count(item.title)>80)return '请填写不超过80个字符的标题。';if(count(item.subtitle)>600||/[\r\n]/.test(item.subtitle))return '副标题最多600个字符，不能换行。';if(count(item.alt)>200)return '图片说明最多200个字符。';if(!Number.isInteger(Number(item.position))||Number(item.position)<0||Number(item.position)>1000000)return '排序须为0至1000000之间的整数。';if(item.kind==='photos'&&!item.media_id)return '请先上传一张自己的照片。';if(item.kind!=='photos'&&!item.url.trim())return '请填写游戏或唱片的目标链接。';if(cover.value)return '请先完成或取消封面上传。';return ''}
async function saveItem(){
 if(locked.value||itemConflict.value||!itemDirty.value)return
 const problem=itemProblem();if(problem){itemError.value=problem;return}
 busy.value='save-item';itemError.value='';message.value=''
 try{
  const photo=activePhoto.value;let result:Row
  if(item.id)result=await api('/admin/home/items/'+item.id,{method:'PUT',version:item.version,body:body(itemValue())})
  else{pendingItem||={key:itemKey,payload:clone(itemValue())};result=await api('/admin/home/items',{method:'POST',key:pendingItem.key,body:body(pendingItem.payload)})}
  if(stopped)return
  const parsed=parseItem(result),preserve=JSON.stringify(itemValue(parsed))!==itemSnapshot();fillItem(parsed,preserve);pendingItem=null
  if(photo){const queued=photos.value.find(p=>p.id===photo);if(queued)release(queued);photos.value=photos.value.filter(p=>p.id!==photo);activePhoto.value=''}
  message.value=preserve?'已确认保存。当前新修改仍未保存。':parsed.visible?'条目已保存为显示。首页区块开启且数量大于0时可展示。':'条目已保存为隐藏。'
  await loadItems()
 }catch(e){itemError.value=(e as Error).message;if(e instanceof APIError&&[409,412].includes(e.status)&&item.id){itemConflict.value=true;itemError.value='条目已在其他位置更新，当前输入已保留。请确认后载入最新条目。'}else if(e instanceof APIError&&[400,422].includes(e.status)){pendingItem=null;itemKey=randomID()}}
 finally{busy.value=''}
}
async function reloadItem(){if(locked.value||!item.id)return;if(itemDirty.value&&!await confirmAction('载入最新条目？','当前条目输入会被服务器内容替换。','载入最新条目'))return;busy.value='read-item';try{const latest=await api('/admin/home/items/'+item.id);if(!stopped){fillItem(latest);itemError.value=''}}catch(e){itemError.value='读取失败，当前输入已保留。'+(e as Error).message}finally{busy.value=''}}
async function deleteItem(row:Row){if(locked.value)return;if(!await confirmAction('删除这条首页内容？',item.id===row.id&&itemDirty.value?'当前未保存的修改也会放弃。图片文件不会删除。':'这会从展示墙移除条目，图片文件不会删除。','删除条目'))return;busy.value='delete-item';listError.value='';try{await api('/admin/home/items/'+row.id,{method:'DELETE',version:row.version});if(item.id===row.id)fillItem();message.value='条目已删除。';await loadItems()}catch(e){listError.value=(e as Error).message+' 请刷新列表后重试。'}finally{busy.value=''}}
async function toggleVisible(row:Row,event:Event){const input=event.target as HTMLInputElement;if(locked.value||(item.id===row.id&&itemDirty.value)){input.checked=row.visible;return}busy.value='visibility';try{const result=parseItem(await api('/admin/home/items/'+row.id,{method:'PUT',version:row.version,body:body({...itemValue(row),visible:input.checked})}));if(item.id===row.id)fillItem(result);await loadItems();message.value=result.visible?'条目已设为显示。':'条目已设为隐藏。'}catch(e){input.checked=row.visible;listError.value=(e as Error).message+' 请刷新列表后重试。'}finally{busy.value=''}}
function parsePlaylistStatus(data:Row):Row{if(!data||!Number.isSafeInteger(Number(data.version))||Number(data.version)<1||['source_url','resolved_url','playlist_id','title','last_error','last_attempt_source_url'].some(k=>typeof data[k]!=='string')||['track_count','album_count'].some(k=>!Number.isSafeInteger(data[k])||data[k]<0)||typeof data.partial!=='boolean')throw new Error('歌单状态不完整，上次记录和当前输入已保留。');return {...data,version:Number(data.version)}}
function parsePlaylistPreview(data:Row):Row{if(!data||['preview_id','source_url','resolved_url','playlist_id','title','expires_at'].some(k=>typeof data[k]!=='string'||!data[k])||['track_count','album_count','preview_count'].some(k=>!Number.isSafeInteger(data[k])||data[k]<0)||typeof data.partial!=='boolean'||!Array.isArray(data.items)||data.preview_count!==data.items.length||data.preview_count>data.album_count||data.album_count>data.track_count||!Number.isFinite(Date.parse(data.expires_at))||data.items.some((r:Row)=>!r||typeof r.title!=='string'||typeof r.url!=='string'||typeof r.image_url!=='string'||typeof r.provider_id!=='string'))throw new Error('歌单预览不完整，原预览和当前条目已保留。');return data}
async function loadPlaylistStatus(){const at=++playlistSequence;playlistLoading.value=true;playlistError.value='';try{const data=parsePlaylistStatus(await api('/admin/home/music-playlist'));if(!stopped&&at===playlistSequence){playlistStatus.value=data;playlistConflict.value=false}}catch(e){if(!stopped&&at===playlistSequence)playlistError.value=(e as Error).message}finally{if(at===playlistSequence)playlistLoading.value=false}}
async function previewPlaylist(refresh=false){
 if(locked.value||!importInput.value.trim())return
 if(pendingPlaylistImport){playlistError.value='上次导入结果尚未确认，请先重试保存本次专辑，或明确取消该预览。';return}
 const input=importInput.value.trim();busy.value='playlist-preview';playlistError.value='';importError.value=''
 if(!pendingPlaylistPreview||pendingPlaylistPreview.input!==input||pendingPlaylistPreview.refresh!==refresh)pendingPlaylistPreview={key:randomID(),input,refresh}
 try{const attempt=pendingPlaylistPreview,data=parsePlaylistPreview(await api('/admin/home/music-playlist/preview',{method:'POST',key:attempt.key,body:body({input:attempt.input,...(attempt.refresh?{refresh:true}:{})})}));if(!stopped){playlistPreview.value=data;playlistInput.value=attempt.input;playlistImportedID.value='';playlistExpired.value=false;pendingPlaylistPreview=null;if(!playlistStatus.value)await loadPlaylistStatus()}}
 catch(e){playlistError.value='未能读取新歌单，原预览和当前条目已保留。'+(e as Error).message;if(e instanceof APIError&&[400,413,422].includes(e.status))pendingPlaylistPreview=null}
 finally{busy.value=''}
}
async function importPlaylist(){
 const preview=playlistPreview.value,status=playlistStatus.value
 if(locked.value||playlistLoading.value||!preview||!status||playlistConflict.value||itemDirty.value||homeDirty.value||photos.value.length||playlistImportedID.value===preview.preview_id||(!pendingPlaylistImport&&playlistInputChanged.value))return
 if(!pendingPlaylistImport&&Date.parse(preview.expires_at)<=Date.now()){playlistExpired.value=true;playlistError.value='预览已过期，原预览仍可查看。请重新读取后再确认保存。';return}
 if(!pendingPlaylistImport&&!await confirmAction(`保存本次 ${preview.album_count} 张专辑？`,`${preview.track_count} 首曲目对应的去重专辑将保存到本地唱片库。新增条目设为显示，已开启的音乐墙会按首页数量公开展示。${preview.partial?'本次未读完整歌单，只保存已读取部分。':''}已有手动、隐藏与排序设置会保留。`,'确认保存本次专辑'))return
 pendingPlaylistImport||={key:randomID(),version:status.version,preview_id:preview.preview_id}
 busy.value='playlist-import';playlistError.value='';message.value=''
 try{const attempt=pendingPlaylistImport,data=parsePlaylistStatus(await api('/admin/home/music-playlist/import',{method:'POST',key:attempt.key,version:attempt.version,body:body({preview_id:attempt.preview_id})}));if(['imported_count','new_count','preserved_count'].some(k=>!Number.isSafeInteger(data[k])||data[k]<0))throw new Error('服务器尚未完整确认导入数量，请重试原批次。');if(!stopped){playlistStatus.value=data;playlistImportedID.value=attempt.preview_id;pendingPlaylistImport=null;playlistConflict.value=false;message.value=`本次专辑已保存。新增 ${data.new_count} 张，保留 ${data.preserved_count} 张既有内容；首页按音乐墙开关和数量展示。`;await loadItems()}}
 catch(e){
  playlistError.value='保存结果未确认，预览和当前条目已保留。可重试同一批次。'+(e as Error).message
  if(e instanceof APIError){
   if(e.code==='HOME_MUSIC_PREVIEW_EXPIRED'){pendingPlaylistImport=null;playlistExpired.value=true;playlistConflict.value=false;playlistError.value='预览已过期或不可再使用，原预览和当前条目已保留。请重新读取后再确认保存。'}
   else if(e.code==='VERSION_CONFLICT'||e.status===412){pendingPlaylistImport=null;playlistConflict.value=true;playlistError.value='歌单状态已变化，原预览和当前条目已保留。请刷新导入状态后再次确认。'}
   else if(e.code==='IDEMPOTENCY_KEY_REUSED'){pendingPlaylistImport=null;playlistConflict.value=true;playlistError.value='本次请求标识已被占用，原预览和当前条目已保留。请刷新导入状态后再次确认。'}
   else if([400,404,410,413,422].includes(e.status)){pendingPlaylistImport=null;playlistExpired.value=[404,410].includes(e.status);playlistError.value='本次未能保存，原预览和当前条目已保留。'+e.message}
  }
 }
 finally{busy.value=''}
}
async function discardPlaylistPreview(){if(locked.value)return;if(pendingPlaylistImport&&!await confirmAction('取消当前歌单预览？','上次保存结果尚未确认。取消预览不会撤销可能已经完成的导入。','取消预览'))return;playlistPreview.value=null;playlistInput.value='';playlistImportedID.value='';playlistExpired.value=false;pendingPlaylistImport=null;pendingPlaylistPreview=null;playlistError.value=''}
async function importMetadata(){if(locked.value||!importInput.value.trim())return;if(isPlaylist.value){await previewPlaylist();return}busy.value='import';importError.value='';try{const data=await api('/admin/home/import',{method:'POST',body:body({kind:kind.value,input:importInput.value.trim()})});if(!stopped)importPreview.value=data}catch(e){importError.value='未能读取链接信息。原预览和当前条目已保留，你仍可手动填写标题、目标链接并上传封面。'+(e as Error).message}finally{busy.value=''}}
async function useImport(){if(locked.value||!importPreview.value)return;if(itemDirty.value&&!await confirmAction('使用导入的信息？','当前未保存的条目会被替换，导入结果仍须核对后保存。','使用导入信息'))return;fillItem();Object.assign(item,{...blankItem(kind.value),...importPreview.value,id:'',version:0,visible:false});itemError.value='';message.value='信息已填入新条目。核对后保存，尚未加入首页。'}
function fileProblem(file:File){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type))return '请选择 JPEG、PNG、WebP 或 GIF 图片。';if(!file.size||file.size>maxBytes.value)return '文件为空或超过 '+sizeLabel.value+'，请重新选择。';return ''}
function uploadRecord(file:File):Upload{const error=fileProblem(file);return {id:randomID(),file,key:randomID(),state:error?'failed':'queued',media_id:'',preview:error?'':URL.createObjectURL(file),error,retryable:!error}}
async function sendUpload(upload:Upload){upload.state='uploading';upload.error='';uploadController=new AbortController();try{const data=new FormData();data.append('file',upload.file,upload.file.name);const result=await api('/media',{method:'POST',key:upload.key,body:data,signal:uploadController.signal});if(stopped)return;if(result.state!=='ready'||typeof result.media_id!=='string')throw new Error('服务器尚未确认图片可用，请重试。');upload.media_id=result.media_id;upload.state='ready'}catch(e){if(!stopped){upload.state='failed';upload.error=(e as Error).message}}finally{uploadController=undefined}}
async function uploadCover(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(locked.value||!file)return;resetCover();cover.value=uploadRecord(file);if(cover.value.state==='queued')await finishCover()}
async function finishCover(){const upload=cover.value;if(!upload||!upload.retryable||busy.value||uploading.value&&upload.state!=='queued')return;await sendUpload(upload);if(!stopped&&upload.state==='ready'){item.media_id=upload.media_id;item.image_url='';resetCover()}}
function cancelCover(){if(locked.value)return;resetCover()}
async function photoUploads(){if(queueRunning||stopped)return;queueRunning=true;try{while(!stopped){const upload=photos.value.find(p=>p.state==='queued');if(!upload)break;await sendUpload(upload)}}finally{queueRunning=false}}
function pickPhotos(event:Event){const input=event.target as HTMLInputElement,files=Array.from(input.files||[]);input.value='';if(locked.value)return;photos.value.push(...files.map(uploadRecord));void photoUploads()}
function retryPhoto(upload:Upload){if(locked.value||!upload.retryable)return;upload.state='queued';void photoUploads()}
async function cancelPhoto(upload:Upload){if(busy.value||upload.state==='uploading')return;if(activePhoto.value===upload.id){itemError.value='这张照片正在编辑。请先保存或新建其他条目。';return}const at=photos.value.indexOf(upload);release(upload);photos.value=photos.value.filter(p=>p.id!==upload.id);await nextTick();document.getElementById(photos.value[Math.min(at,photos.value.length-1)]?uid+'-photo-'+photos.value[Math.min(at,photos.value.length-1)].id:uid+'-photos-add')?.focus()}
async function reviewPhoto(upload:Upload){if(locked.value||upload.state!=='ready')return;if(itemDirty.value&&!await confirmAction('编辑这张照片？','当前未保存的条目输入将被替换。','编辑照片'))return;fillItem();Object.assign(item,{...blankItem('photos'),title:Array.from(upload.file.name.replace(/\.[^.]+$/,'')).slice(0,80).join(''),media_id:upload.media_id});activePhoto.value=upload.id;await nextTick();document.getElementById(uid+'-item-title')?.focus()}
async function syncSteam(){if(locked.value||dirty.value||!credentialsReady.value||!ready.value)return;busy.value='sync';homeError.value='';message.value='';try{const data=await api('/admin/home/steam-sync',{method:'POST',version:version.value,key:syncKey});if(!stopped){applyHome(data);syncKey=randomID();message.value=`Steam 同步完成，本次处理 ${Number(data.synced_count)||0} 项。`;if(kind.value==='steam')await loadItems()}}catch(e){homeError.value=(e as Error).message;if(e instanceof APIError&&[409,412].includes(e.status))homeConflict.value=true}finally{busy.value=''}}
function date(value:unknown){if(!value)return '尚未同步';const d=new Date(typeof value==='number'?value:/^\d{13}$/.test(String(value))?Number(value):String(value));return Number.isNaN(d.valueOf())?'尚未同步':d.toLocaleString('zh-CN')}
function playtime(value:unknown){return value===null?'未知':new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(Number(value)/60)+' 小时'}
function sourceLabel(row:Row){return row.source==='steam_sync'?'Steam 同步':row.source==='music_playlist'?'歌单导入':'手动添加'}

const activityScroll=ref<HTMLElement>()
const activityPreview=ref<Row|null>(null),activityError=ref(''),activitySnapshot=ref(''),activityLoading=ref(false)
const activityChanged=computed(()=>!!activityPreview.value&&JSON.stringify(config.value.activity)!==activitySnapshot.value)
const browserTimezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Shanghai'
const activityZones=computed(()=>Array.from(new Set(['Asia/Shanghai',browserTimezone,config.value.activity?.timezone,'UTC','America/New_York','Europe/London'].filter(Boolean))).map(value=>({value,label:value==='Asia/Shanghai'?'北京时间 · Asia/Shanghai':value})))
async function previewActivity(){if(locked.value||activityLoading.value)return;activityError.value='';activityLoading.value=true;const snapshot=JSON.stringify(config.value.activity);try{const data=await api('/admin/home/activity?'+new URLSearchParams(Object.fromEntries(Object.entries(config.value.activity).map(([k,v])=>[k,String(v)]))));if(!stopped){activityPreview.value=data;activitySnapshot.value=snapshot;await nextTick();const scroll=activityScroll.value,latest=scroll?.querySelectorAll<HTMLElement>('[data-in-range=true]');if(scroll&&latest?.length){const day=latest[latest.length-1];scroll.scrollLeft+=day.getBoundingClientRect().right-scroll.getBoundingClientRect().right+6}}}catch(e){if(!stopped)activityError.value=(e as Error).message}finally{activityLoading.value=false}}
const projects=ref<Row[]>([]),projectsLoading=ref(false),projectError=ref(''),projectListError=ref(''),projectConflict=ref(false),project=reactive<Row>({}),projectInitial=ref('')
const projectActions=new Map<string,string>()
let pendingProject:{key:string;payload:Row;id:string;version:number}|null=null
function projectValue(value:Row=project):Row{return {source:value.source,repo_url:value.source==='github'?value.repo_url:'',title:value.source==='manual'||value.custom_title?value.title:null,description:value.source==='manual'||value.custom_description?value.description:null,url:value.source==='manual'||value.custom_url?value.url:null,language:value.source==='manual'||value.custom_language?value.language:null,position:value.position,visible:value.visible}}
const projectDirty=computed(()=>JSON.stringify(projectValue())!==projectInitial.value)
function fillProject(row?:Row){Object.assign(project,{id:'',version:0,source:'github',repo_url:'',title:'',description:'',url:'',language:'',position:0,visible:false,custom_title:false,custom_description:false,custom_url:false,custom_language:false},row||{});if(row){for(const key of ['title','description','url','language'])project['custom_'+key]=row[key+'_override']!==null}projectInitial.value=JSON.stringify(projectValue());projectConflict.value=false;pendingProject=null}
fillProject()
async function loadProjects(){if(projectsLoading.value)return;projectsLoading.value=true;projectListError.value='';try{const data=await api('/admin/home/projects');if(!stopped){const rows=list(data);if(rows.some(r=>!String(r.id||'')||!Number.isSafeInteger(r.version)||r.version<1||!['github','manual'].includes(r.source)||typeof r.visible!=='boolean'))throw new Error('项目列表未完整载入，请重试。');projects.value=rows}}catch(e){if(!stopped)projectListError.value=(e as Error).message}finally{projectsLoading.value=false}}
async function editProject(row?:Row){if(locked.value)return;if(projectDirty.value&&!await confirmAction('载入项目？','当前未保存的项目修改将被替换。','载入项目'))return;fillProject(row);projectError.value='';await nextTick();document.getElementById(uid+'-project-source')?.focus()}
async function saveProject(){if(locked.value||!projectDirty.value||projectConflict.value)return;const payload=projectValue();if(payload.source==='github'&&!payload.repo_url.trim()){projectError.value='请填写公开 GitHub 仓库链接或 owner/repo。';return}if(payload.source==='manual'&&(!payload.title?.trim()||!payload.url?.trim())){projectError.value='请填写项目标题和链接。';return}busy.value='save-project';projectError.value='';const attempt=pendingProject||{key:randomID(),payload:clone(payload),id:project.id,version:project.version};pendingProject=attempt;try{const row=await api('/admin/home/projects'+(attempt.id?'/'+attempt.id:''),{method:attempt.id?'PUT':'POST',key:attempt.key,version:attempt.version,body:body(attempt.payload)});if(!stopped){fillProject(row);await loadProjects();message.value=row.source==='github'?'项目已保存。点击「刷新资料」可从 GitHub 读取公开信息。':'项目已保存。'}}catch(e){projectError.value=(e as Error).message;if(e instanceof APIError&&[409,412].includes(e.status)){projectConflict.value=true;pendingProject=null}else if(e instanceof APIError&&e.status<500)pendingProject=null}finally{busy.value=''}}
function projectActionKey(action:string,row:Row){const id=action+':'+row.id+':'+row.version;if(!projectActions.has(id))projectActions.set(id,randomID());return projectActions.get(id)!}
async function projectAction(row:Row,action:'refresh'|'delete'){if(locked.value)return;if(project.id===row.id&&projectDirty.value){projectError.value='请先保存或放弃当前项目修改。';return}if(action==='delete'&&!await confirmAction('删除这个项目？',row.title+' 将从项目库移除。','删除项目'))return;busy.value=action+'-project';projectListError.value='';try{const data=await api('/admin/home/projects/'+row.id+(action==='refresh'?'/refresh':''),{method:action==='refresh'?'POST':'DELETE',key:projectActionKey(action,row),version:row.version});if(!stopped){if(action==='delete'&&project.id===row.id)fillProject();if(action==='refresh'&&project.id===row.id)fillProject(data);await loadProjects();message.value=action==='delete'?'项目已删除。':data.last_error||'GitHub 资料已刷新，自定义文字已保留。'}}catch(e){projectListError.value=(e as Error).message+' 可刷新项目列表后重试。'}finally{busy.value=''}}
async function projectVisibility(row:Row,event:Event){const input=event.target as HTMLInputElement;if(locked.value||(project.id===row.id&&projectDirty.value)){input.checked=row.visible;return}busy.value='project-visibility';try{const value={...row};for(const key of ['title','description','url','language'])value['custom_'+key]=row[key+'_override']!==null;const data=await api('/admin/home/projects/'+row.id,{method:'PUT',version:row.version,key:projectActionKey('visible-'+input.checked,row),body:body({...projectValue(value),visible:input.checked})});if(!stopped){if(project.id===row.id)fillProject(data);await loadProjects()}}catch(e){input.checked=row.visible;projectListError.value=(e as Error).message+' 请刷新项目列表后重试。'}finally{busy.value=''}}
async function reloadProject(){await loadProjects();const row=projects.value.find(r=>r.id===project.id);if(row)await editProject(row);else projectError.value='列表中已找不到这个项目，当前输入已保留。'}

function beforeLeave(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>{void loadHome();void loadItems();void loadProjects();window.addEventListener('beforeunload',beforeLeave)})
onBeforeUnmount(()=>{stopped=true;sequence++;playlistSequence++;listController?.abort();uploadController?.abort();resetCover();photos.value.forEach(release);window.removeEventListener('beforeunload',beforeLeave)})
</script>

<template>
 <div class="homepage-manager">
  <div class="homepage-topbar"><div class="homepage-tabs" role="tablist" aria-label="首页管理分区" @keydown="tabKey"><button v-for="tab in [{id:'content',label:'页面内容'},{id:'walls',label:'展示墙'},{id:'projects',label:'项目卡片'},{id:'steam',label:'Steam 设置'}]" :id="uid+'-tab-'+tab.id" :key="tab.id" type="button" role="tab" :aria-selected="view===tab.id" :tabindex="view===tab.id?0:-1" :aria-controls="uid+'-panel-'+tab.id" @click="view=tab.id">{{tab.label}}</button></div><a class="button quiet" href="/" target="_blank" rel="noopener">查看首页<Icon name="arrow" :size="16"/></a></div>
  <p v-if="message" class="homepage-feedback" role="status">{{message}}</p>
  <p v-if="homeError" class="homepage-feedback is-error" role="alert">{{homeError}} <button type="button" :disabled="locked||loadingHome" @click="loadHome(true)">{{homeConflict?'载入最新设置':'重新载入设置'}}</button></p>
  <p v-if="loadingHome" class="homepage-loading" role="status">正在载入首页设置…</p>
  <template v-if="ready">
   <section :id="uid+'-panel-content'" v-show="view==='content'" role="tabpanel" :aria-labelledby="uid+'-tab-content'">
    <form class="homepage-config-form" @submit.prevent="saveHome">
     <div class="homepage-config-grid"><section class="homepage-order" aria-label="首页区块顺序"><h2>显示与顺序</h2><p class="homepage-help">从上到下依次展示。未开启的区块不会出现在首页。</p><p class="homepage-scroll-hint">左右滑动可查看完整操作。</p><div class="homepage-table-scroll" tabindex="0" aria-label="首页区块表格，可横向滚动"><table class="homepage-table homepage-sections-table"><thead><tr><th scope="col">区块</th><th scope="col">显示</th><th scope="col">顺序</th><th scope="col">内容</th></tr></thead><tbody><tr v-for="(key,index) in config.order" :id="uid+'-section-'+key" :key="key" tabindex="-1" :class="{'is-current':section===key}"><th scope="row">{{names[key]}}</th><td><label class="homepage-check"><input v-model="config.sections[key].enabled" type="checkbox" :disabled="locked"><span class="sr-only">显示{{names[key]}}</span></label></td><td><div class="homepage-row-actions"><button type="button" :aria-label="'将'+names[key]+'上移'" :disabled="locked||index===0" @click="moveSection(index,-1)">上移</button><button type="button" :aria-label="'将'+names[key]+'下移'" :disabled="locked||index===config.order.length-1" @click="moveSection(index,1)">下移</button></div></td><td><button type="button" class="quiet" :aria-label="'编辑'+names[key]+'内容'" :aria-pressed="section===key" @click="editSection(key)">编辑</button></td></tr></tbody></table></div></section>
     <section v-if="selectedSection" :id="uid+'-section-editor'" class="homepage-section-editor" tabindex="-1" :aria-label="names[section]+'设置'"><h2>{{names[section]}}</h2><div class="homepage-fields"><label>{{section==='intro'?'开场问候':'标题'}} <textarea v-model="selectedSection.title" rows="2" :disabled="locked"></textarea><small>最多80字符，支持换行。</small></label><template v-if="section==='intro'"><label class="check"><input v-model="config.use_site_intro" type="checkbox" :disabled="locked">沿用网站姓名、简介与身份</label><p class="homepage-help">网站介绍可在<a href="/studio/settings#site">网站信息</a>修改。关闭沿用后，为首页单独填写。</p><template v-if="!config.use_site_intro"><label>首页姓名<input v-model="config.intro_name" :disabled="locked"><small>最多80字符。</small></label><label>身份与兴趣<input v-model="roles" :disabled="locked" placeholder="用顿号或逗号分隔"><small>最多12项，每项60字符。</small></label></template></template><label>介绍 <textarea v-model="selectedSection.description" rows="3" :disabled="locked||(section==='intro'&&config.use_site_intro)"></textarea><small>{{section==='intro'&&config.use_site_intro?'当前沿用网站简介。':'最多600字符，支持换行。'}}</small></label><label v-if="['articles','steam','music','photos','projects'].includes(section)">显示数量<input v-model.number="selectedSection.limit" type="number" min="0" :max="section==='articles'?12:24" :disabled="locked"><small>{{section==='articles'?'0 隐藏文章区块，最多12篇。':section==='steam'?'首页最多5项，0隐藏；完整游戏墙展示全部。当前值超过5时，首页仍只显示5项。':'0 或没有可展示条目时隐藏该墙，最多24项。'}}</small></label><template v-if="section==='activity'">
       <SelectField v-model="config.activity.source" label="统计来源" :disabled="locked" :options="[{value:'posts_moments',label:'公开文章与瞬间'},{value:'posts',label:'仅公开文章'},{value:'moments',label:'仅公开瞬间'}]"/>
       <SelectField v-model="config.activity.period" label="时间范围" :disabled="locked" :options="[{value:'rolling',label:'最近365天'},{value:'year',label:'按自然年'}]"/>
       <label v-if="config.activity.period==='year'">统计年份<input v-model.number="config.activity.year" type="number" min="0" max="2100" :disabled="locked"><small>0 跟随当前年份；指定年份为2000至2100。</small></label>
       <SelectField v-model="config.activity.timezone" label="按此时区划分日期" :disabled="locked" :options="activityZones"/>
       <p class="homepage-help">每篇目前公开的文章、每条公开瞬间，按首次发布时间计1次。草稿与编辑不增加次数，撤回或删除后不计入。绿色圆点反映博客发布频率。</p>
       <button type="button" :disabled="locked||activityLoading" @click="previewActivity">{{activityLoading?'正在读取…':'预览真实发布记录'}}</button>
       <p v-if="activityError" class="homepage-feedback is-error" role="alert">{{activityError}}</p>
       <div v-if="activityPreview" class="homepage-activity-preview"><p>{{activityPreview.start}} — {{activityPreview.end}} · {{activityPreview.total}} 次发布 · {{activityPreview.active_days}} 天有记录</p><p v-if="activityChanged" class="homepage-help">统计设置已变化，重新预览可查看当前范围。</p><div ref="activityScroll" class="homepage-activity-scroll" tabindex="0" aria-label="真实发布频率预览，可横向滚动"><div class="homepage-activity-grid"><div v-for="(week,wi) in activityPreview.weeks" :key="wi" class="homepage-activity-week"><span v-for="day in week" :key="day.date" :data-level="day.level" :data-in-range="day.in_range&&!day.future" :title="day.date+'：'+day.count+' 次发布'" :aria-label="day.date+'：'+day.count+' 次发布'"></span></div></div></div><p class="homepage-help">左右滑动查看更多日期；悬停或点击格子查看当天记录。</p><p v-if="activityPreview.total===0" class="homepage-help">此范围内尚无符合来源的公开发布记录。</p></div>
      </template><div class="homepage-field-pair"><label>链接文字<input v-model="selectedSection.link_label" :disabled="locked"><small>{{section==='steam'?'选填，留空显示“查看更多游戏”。':'选填，最多60字符。'}}</small></label><label>链接地址<input v-if="section==='steam'" value="/games" readonly><input v-else v-model="selectedSection.link_url" :disabled="locked" placeholder="/posts 或 https://…"><small v-if="section==='steam'">查看更多固定进入 /games</small></label></div></div></section></div>
     <details class="homepage-common"><summary>写作场景与滚动</summary><div class="homepage-fields"><div class="homepage-field-pair"><label>写作标题<textarea v-model="config.writing_title" rows="2" :disabled="locked"></textarea><small>最多80字符。</small></label><label>写作介绍<textarea v-model="config.writing_description" rows="3" :disabled="locked"></textarea><small>最多600字符。</small></label></div><label>向下探索提示<input v-model="config.scroll_label" :disabled="locked"><small>最多60字符。</small></label><div class="homepage-checks"><label class="check"><input v-model="config.motion_enabled" type="checkbox" :disabled="locked">启用滚动视差</label><label class="check"><input v-model="config.warmth_enabled" type="checkbox" :disabled="locked">滚动时渐变背景</label></div></div></details>
     <div class="homepage-savebar"><span>{{homeDirty?'有未保存的首页设置':'首页设置已保存'}}</span><button class="primary" :disabled="locked||!homeDirty||homeConflict">{{busy==='save-home'?'正在保存…':'保存首页设置'}}</button></div>
    </form>
   </section>

   <section :id="uid+'-panel-walls'" v-show="view==='walls'" role="tabpanel" :aria-labelledby="uid+'-tab-walls'">
    <div class="homepage-wall-toolbar"><SelectField :model-value="kind" label="展示墙" :options="kinds" :disabled="locked||loadingItems" @update:model-value="changeKind"/><p class="homepage-help">首页展示数量在「页面内容」设置，不限制这里的分页内容库。</p><button type="button" :disabled="locked" @click="editItem()">新建条目</button><button v-if="kind==='photos'" :id="uid+'-photos-add'" type="button" :disabled="locked" @click="photoInput?.click()">选择多张照片</button></div>
    <p v-if="listError" class="homepage-feedback is-error" role="alert">{{listError}} <button type="button" :disabled="locked||loadingItems" @click="loadItems">刷新条目</button></p>
    <div class="homepage-library-grid"><section class="homepage-library" aria-label="展示墙条目"><p class="homepage-scroll-hint">左右滑动可查看完整操作。</p><div class="homepage-table-scroll" tabindex="0" aria-label="展示墙条目表格，可横向滚动" :aria-busy="loadingItems"><table class="homepage-table homepage-items-table"><thead><tr><th scope="col">图片 / 标题</th><th scope="col">显示</th><th scope="col">排序</th><th scope="col">操作</th></tr></thead><tbody><tr v-if="loadingItems"><td colspan="4" role="status">正在载入条目…</td></tr><tr v-for="row in items" :key="row.id"><td><div class="homepage-item-cell"><img v-if="row.media_id||row.image_url" :src="row.media_id?'/media/'+row.media_id:row.image_url" :alt="row.alt||''" width="48" height="48" loading="lazy"><span v-else class="homepage-item-noimage"><Icon name="image" :size="20"/></span><div><strong>{{row.title}}</strong><small>{{row.subtitle||sourceLabel(row)}}</small><small v-if="row.local_override">已自定义，后续更新保留</small><small v-if="row.kind==='steam'">{{row.playtime_minutes===null?'游玩时长未知':playtime(row.playtime_minutes)}}</small></div></div></td><td><label class="homepage-check"><input type="checkbox" :checked="row.visible" :disabled="locked||(item.id===row.id&&itemDirty)" :aria-label="'在首页显示'+row.title" @change="toggleVisible(row,$event)"></label></td><td class="homepage-position">{{row.position}}</td><td><div class="homepage-row-actions"><button type="button" :disabled="locked" @click="editItem(row)">编辑</button><button type="button" class="quiet danger" :disabled="locked" @click="deleteItem(row)">删除</button></div></td></tr><tr v-if="!loadingItems&&!items.length&&!listError"><td colspan="4"><strong>还没有{{names[kind]}}条目</strong><p class="homepage-help">添加自己的内容，保存后再决定是否显示。</p></td></tr></tbody></table></div><div class="homepage-pagination"><span>{{loadingItems?'正在更新…':listError?'列表未载入':`第 ${page+1} 页 · 本页 ${items.length} 项`}}</span><div><button type="button" :disabled="locked||loadingItems||page===0" @click="paginate(-1)">上一页</button><button type="button" :disabled="locked||loadingItems||!nextCursor" @click="paginate(1)">下一页</button></div></div></section>
     <form class="homepage-item-editor" @submit.prevent="saveItem"><div class="homepage-editor-heading"><h2>{{item.id?'编辑条目':'新建条目'}}</h2><button type="button" class="quiet" :disabled="locked" @click="editItem()">新建</button></div><p v-if="itemError" class="homepage-feedback is-error" role="alert">{{itemError}} <button v-if="itemConflict" type="button" :disabled="locked" @click="reloadItem">载入最新条目</button></p>
      <details v-if="kind!=='photos'" class="homepage-import"><summary>从{{kind==='steam'?'Steam':'Apple Music'}}链接读取信息</summary>
       <label>{{kind==='steam'?'商店链接或 App ID':'Apple Music 专辑或公开歌单链接'}}<input v-model="importInput" :disabled="locked" :placeholder="kind==='steam'?'Steam 商店链接或 App ID':'粘贴完整专辑或公开歌单链接'"></label>
       <button type="button" :disabled="locked||!importInput.trim()" @click="importMetadata">{{busy==='import'||busy==='playlist-preview'?'正在读取…':isPlaylist?'读取歌单预览':'读取链接信息'}}</button>
       <p v-if="importError" class="homepage-feedback is-error" role="alert">{{importError}}</p>
       <div v-if="importPreview&&!isPlaylist" class="homepage-import-preview"><img v-if="importPreview.image_url" :src="importPreview.image_url" alt="平台封面预览" width="64" height="64"><div><strong>{{importPreview.title}}</strong><p>{{importPreview.subtitle}}</p></div><button type="button" :disabled="locked" @click="useImport">用于新条目</button></div>
       <template v-if="kind==='music'">
        <p v-if="playlistLoading" class="homepage-help" role="status">正在读取歌单导入状态…</p>
        <div v-if="playlistStatus?.last_success_at" class="homepage-playlist-status"><strong>上次保存的歌单：{{playlistStatus.title}}</strong><p>{{playlistStatus.track_count}} 首已读取曲目 · {{playlistStatus.album_count}} 张去重专辑{{playlistStatus.partial?' · 未读取完整歌单':''}}</p><small>保存于 {{date(playlistStatus.last_success_at)}}</small><p v-if="playlistStatus.last_error" class="homepage-feedback is-error">{{playlistStatus.last_error}}</p></div>
        <p v-else-if="playlistStatus&&!playlistLoading" class="homepage-help">尚未保存歌单。读取预览后，核对本次内容并确认保存。</p>
        <p v-if="playlistError" class="homepage-feedback is-error" role="alert">{{playlistError}}</p>
        <button v-if="playlistConflict||(!playlistStatus&&!playlistLoading)" type="button" :disabled="locked||playlistLoading" @click="loadPlaylistStatus">刷新导入状态</button>
        <section v-if="playlistPreview" class="homepage-playlist-preview" aria-label="本次歌单预览">
         <h3>{{playlistPreview.title}}</h3><dl class="homepage-playlist-counts"><div><dt>本次读取曲目</dt><dd>{{playlistPreview.track_count}} 首</dd></div><div><dt>本次去重专辑</dt><dd>{{playlistPreview.album_count}} 张</dd></div><div><dt>当前预览专辑</dt><dd>{{playlistPreview.preview_count}} 张</dd></div></dl>
         <p v-if="playlistPreview.partial" class="homepage-playlist-partial" role="status">未读取完整歌单，只保存本次已读取的部分。</p>
         <p class="homepage-help">这里仅展示前 {{playlistPreview.preview_count}} 张封面；确认后保存本次 {{playlistPreview.album_count}} 张去重专辑，包含当前未展示的已读取专辑。</p>
         <a class="homepage-playlist-source" :href="playlistPreview.source_url" target="_blank" rel="noopener">打开来源歌单<Icon name="arrow" :size="16"/></a>
         <ol class="homepage-playlist-albums" tabindex="0" aria-label="本次歌单专辑预览，可滚动"><li v-for="(album,index) in playlistPreview.items" :key="album.provider_id||index"><img v-if="album.image_url" :src="album.image_url" :alt="album.title+'封面'" width="64" height="64" loading="lazy"><strong>{{album.title}}</strong><small>{{album.subtitle}}</small></li></ol>
         <p v-if="playlistPreview.notice" class="homepage-help">{{playlistPreview.notice}}</p>
         <p class="homepage-help">预览有效至 {{date(playlistPreview.expires_at)}}。新导入专辑设为显示，已开启的音乐墙会按首页数量公开展示；已有手动、隐藏、排序和自选封面保留。</p>
         <p v-if="playlistInputChanged" class="homepage-playlist-partial">链接已更改，当前仍是原歌单预览。重新读取后再确认保存。</p>
         <p v-if="playlistExpired" class="homepage-playlist-partial">预览已过期，请重新读取；当前预览仍可查看。</p>
         <div class="homepage-playlist-actions"><button type="button" class="primary" :disabled="locked||playlistLoading||!playlistStatus||playlistConflict||itemDirty||homeDirty||photos.length>0||(!pendingPlaylistImport&&(playlistInputChanged||playlistExpired))||playlistPreview.album_count===0||playlistImportedID===playlistPreview.preview_id" @click="importPlaylist">{{busy==='playlist-import'?'正在保存…':playlistImportedID===playlistPreview.preview_id?'本次已保存':pendingPlaylistImport?'重试保存本次专辑':`确认保存本次 ${playlistPreview.album_count} 张专辑`}}</button><button type="button" :disabled="locked||!!pendingPlaylistImport||!isPlaylist" @click="previewPlaylist(true)">重新读取最新预览</button><button type="button" class="quiet" :disabled="locked" @click="discardPlaylistPreview">取消预览</button></div>
         <p v-if="itemDirty||homeDirty" class="homepage-help">请先保存或放弃当前条目 / 首页设置修改，再确认歌单导入。</p>
        </section>
       </template>
       <p class="homepage-help">{{kind==='steam'?'读取商店信息后核对保存，也可以手动填写。':'支持公开专辑与歌单，不读取私人播放历史。歌单可能只返回部分曲目，预览会注明本次读取范围。'}}</p>
      </details>
      <div class="homepage-fields"><label :for="uid+'-item-title'">标题<input :id="uid+'-item-title'" v-model="item.title" :disabled="locked" required><small>{{count(item.title)}} / 80 字符</small></label><label>副标题<input v-model="item.subtitle" :disabled="locked"><small>选填，最多600字符。</small></label><label>目标链接<input v-model="item.url" :disabled="locked" placeholder="https://…"><small>{{kind==='photos'?'选填，可链接到更多照片。':'游戏商店或 Apple Music 专辑链接。'}}</small></label><div v-if="imageSource" class="homepage-cover-preview"><img :src="imageSource" :alt="item.alt||'条目图片预览'"></div><div class="homepage-cover-actions"><button type="button" :disabled="locked" @click="fileInput?.click()"><Icon name="image" :size="16"/>{{kind==='photos'?'上传照片':'上传自选封面'}}</button><input ref="fileInput" class="sr-only" type="file" tabindex="-1" aria-label="上传首页条目图片" accept="image/jpeg,image/png,image/webp,image/gif" :disabled="locked" @change="uploadCover"><button v-if="item.media_id&&!cover" type="button" class="quiet" :disabled="locked" @click="item.media_id=''">移除自选图片</button></div><div v-if="cover" class="homepage-upload-state" role="status"><p>{{cover.state==='uploading'?'正在上传图片…':cover.error}}</p><progress v-if="cover.state==='uploading'" aria-label="正在上传条目图片"></progress><button v-if="cover.state==='failed'&&cover.retryable" type="button" :disabled="locked" @click="finishCover">重试原文件</button><button v-if="cover.state==='failed'" type="button" class="quiet" :disabled="locked" @click="cancelCover">取消上传</button></div><p class="homepage-help">图片最大 {{sizeLabel}}。上传后仍须保存条目；移除引用不会删除媒体文件。</p><label>图片说明<textarea v-model="item.alt" rows="2" :disabled="locked"></textarea><small>{{count(item.alt)}} / 200 字符</small></label><div class="homepage-field-pair"><label>排序<input v-model.number="item.position" type="number" min="0" max="1000000" :disabled="locked"><small>数字较小的在前。</small></label><label class="check"><input v-model="item.visible" type="checkbox" :disabled="locked">在首页显示</label></div><details v-if="kind==='steam'" class="homepage-game-art"><summary>沉浸展示素材与游玩时长</summary><label>Steam Hero 地址<input v-model="item.hero_url" :disabled="locked" placeholder="https://…"><small>官方 Steam 横版素材，留空自动使用官方图片。</small></label><label>Steam Logo 地址<input v-model="item.logo_url" :disabled="locked" placeholder="https://…"><small>留空自动使用官方标识；素材不可用时显示游戏标题。</small></label><div class="homepage-game-playtime"><span>累计游玩时长</span><output aria-label="累计游玩时长">{{playtime(item.playtime_minutes)}}</output><small>{{item.playtime_minutes===null?'Steam 尚未返回时长，未知不按0计算。':item.playtime_minutes+' 分钟，由 Steam 同步更新。'}}</small></div></details><details v-if="kind!=='photos'" class="homepage-item-advanced"><summary>平台编号与图片地址</summary><label>平台编号<input v-model="item.provider_id" :disabled="locked"></label><label>平台图片地址<input v-model="item.image_url" :disabled="locked||!!item.media_id" placeholder="https://…"></label><p class="homepage-help">只接受 Steam / Apple 官方图片地址，其他封面请上传。</p></details></div>
      <div class="homepage-item-save"><span>{{itemDirty?'有未保存的修改':'没有未保存的修改'}}</span><button class="primary" :disabled="locked||!itemDirty||itemConflict">{{busy==='save-item'?'正在保存…':'保存条目'}}</button></div><p class="homepage-help">此单条编辑器新建默认隐藏。勾选显示并保存后，还需在「页面内容」开启该墙并设置数量。</p>
     </form></div>
    <section v-if="kind==='photos'" class="homepage-photo-batch" aria-label="批量上传照片"><div class="homepage-editor-heading"><div><h2>多张照片</h2><p class="homepage-help">依次上传，每张核对标题与说明后单独保存；不会自动公开。</p></div><button type="button" :disabled="locked" @click="photoInput?.click()">继续添加照片</button><input ref="photoInput" class="sr-only" type="file" multiple tabindex="-1" aria-label="批量选择首页照片" accept="image/jpeg,image/png,image/webp,image/gif" :disabled="locked" @change="pickPhotos"></div><ul v-if="photos.length" class="homepage-photo-queue"><li v-for="photo in photos" :id="uid+'-photo-'+photo.id" :key="photo.id" :data-upload-state="photo.state" tabindex="-1"><img v-if="photo.preview||photo.media_id" :src="photo.preview||'/media/'+photo.media_id" alt="待核对照片" width="56" height="56"><div><strong>{{photo.file.name}}</strong><span role="status">{{photo.state==='queued'?'等待上传':photo.state==='uploading'?'正在上传…':photo.state==='ready'?'已上传，尚未保存':photo.error}}</span><progress v-if="photo.state==='uploading'" aria-label="正在上传照片"></progress></div><div class="homepage-row-actions"><button v-if="photo.state==='ready'" type="button" :disabled="locked" @click="reviewPhoto(photo)">编辑并保存</button><button v-if="photo.state==='failed'&&photo.retryable" type="button" :disabled="locked" @click="retryPhoto(photo)">重试</button><button type="button" class="quiet danger" :disabled="!!busy||photo.state==='uploading'" @click="cancelPhoto(photo)">{{photo.state==='ready'?'移除待保存项':'取消'}}</button></div></li></ul></section>
   </section>

   <section :id="uid+'-panel-projects'" v-show="view==='projects'" role="tabpanel" :aria-labelledby="uid+'-tab-projects'">
    <div class="homepage-wall-toolbar"><p class="homepage-help">维护自己的项目。显示开关、数量、标题与顺序在「页面内容 → 项目卡片」设置。</p><button type="button" :disabled="locked" @click="editProject()">添加项目</button><button type="button" :disabled="locked||projectsLoading" @click="loadProjects">刷新项目列表</button></div>
    <p v-if="projectListError" class="homepage-feedback is-error" role="alert">{{projectListError}}</p>
    <div class="homepage-library-grid"><section class="homepage-library" aria-label="项目库"><p v-if="projectsLoading" role="status" class="homepage-help">正在载入项目…</p><ol class="homepage-project-list"><li v-for="row in projects" :key="row.id"><div class="homepage-project-summary"><strong>{{row.title}}</strong><small>{{row.source==='github'?row.repo_url:'手动项目'}}</small><p>{{row.description||(row.fetched_at?'这个仓库没有公开简介。':'保存后可刷新 GitHub 资料，也可自定义简介。')}}</p><small>排序 {{row.position}} · {{row.source==='github'?(row.stars===null?'星标未知':row.stars+' 星标'):'手动维护'}}{{row.fetched_at?' · 读取于 '+date(row.fetched_at):''}}</small><p v-if="row.last_error" class="homepage-project-error">{{row.last_error}}</p></div><div class="homepage-project-actions"><label class="check"><input type="checkbox" :checked="row.visible" :disabled="locked||(project.id===row.id&&projectDirty)" @change="projectVisibility(row,$event)">显示</label><button type="button" :disabled="locked" @click="editProject(row)">编辑</button><button v-if="row.source==='github'" type="button" :disabled="locked||(project.id===row.id&&projectDirty)" @click="projectAction(row,'refresh')">{{busy==='refresh-project'?'正在读取…':'刷新资料'}}</button><button type="button" class="quiet danger" :disabled="locked" @click="projectAction(row,'delete')">删除</button></div></li></ol><p v-if="!projectsLoading&&!projects.length&&!projectListError" class="homepage-help">还没有项目。添加公开 GitHub 仓库，或手动填写项目；新项目默认隐藏。</p></section>
     <form class="homepage-item-editor" @submit.prevent="saveProject"><div class="homepage-editor-heading"><h2>{{project.id?'编辑项目':'添加项目'}}</h2></div><p v-if="projectError" class="homepage-feedback is-error" role="alert">{{projectError}} <button v-if="projectConflict" type="button" :disabled="locked" @click="reloadProject">载入最新项目</button></p><div class="homepage-fields"><div :id="uid+'-project-source'" tabindex="-1"><SelectField v-model="project.source" label="项目来源" :disabled="locked" :options="[{value:'github',label:'公开 GitHub 仓库'},{value:'manual',label:'手动维护'}]"/></div><label v-if="project.source==='github'">仓库地址<input v-model="project.repo_url" :disabled="locked" placeholder="https://github.com/owner/repo"><small>支持 owner/repo；保存后点击「刷新资料」。不需要密钥。</small></label>
      <template v-for="field in [{key:'title',label:'标题',max:80},{key:'description',label:'简介',max:600},{key:'url',label:'项目链接',max:2048},{key:'language',label:'语言',max:80}]" :key="field.key"><label v-if="project.source==='github'" class="check"><input v-model="project['custom_'+field.key]" type="checkbox" :disabled="locked">自定义{{field.label}}</label><label v-if="project.source==='manual'||project['custom_'+field.key]">{{field.label}}<textarea v-if="field.key==='description'" v-model="project[field.key]" rows="3" :disabled="locked"></textarea><input v-else v-model="project[field.key]" :disabled="locked"><small>最多{{field.max}}字符{{project.source==='github'?'；刷新保留此自定义内容。':''}}</small></label></template>
      <label>排序<input v-model.number="project.position" type="number" min="0" max="1000000" :disabled="locked"><small>较小的在前，同值按添加顺序。可随时修改。</small></label><label class="check"><input v-model="project.visible" type="checkbox" :disabled="locked">在首页显示</label><p class="homepage-help">GitHub 星标、语言、简介与更新时间来自最近一次手动刷新。无法读取时保留已保存资料；未知星标不会显示为0。</p></div><div class="homepage-item-save"><span>{{projectDirty?'有未保存的修改':'没有未保存的修改'}}</span><button class="primary" :disabled="locked||!projectDirty||projectConflict">{{busy==='save-project'?'正在保存…':'保存项目'}}</button></div></form>
    </div>
   </section>

   <section :id="uid+'-panel-steam'" v-show="view==='steam'" role="tabpanel" :aria-labelledby="uid+'-tab-steam'">
    <form class="homepage-steam-form" @submit.prevent="saveHome"><h2>Steam 游戏同步</h2><p class="homepage-help">填写自己的 Steam ID64 和 Web API Key。启用后每6小时尝试同步，资料是否可读取仍取决于 Steam 隐私设置。</p><div class="homepage-fields"><label>Steam ID64<input v-model="steam.steam_id" inputmode="numeric" :disabled="locked" placeholder="17位数字"></label><label>Steam Web API Key<input v-model="apiKey" type="password" autocomplete="new-password" :disabled="locked" :placeholder="steamStatus.api_key_configured?'已配置，留空保持':'尚未配置'" @input="clearKey=false"><small>{{steamStatus.api_key_configured?'密钥已保存，不回显。':'保存密钥后才能同步。'}}</small></label><label v-if="steamStatus.api_key_configured" class="check"><input v-model="clearKey" type="checkbox" :disabled="locked" @change="clearKey&&(apiKey='')">移除已保存的 API Key</label><SelectField v-model="steam.mode" label="同步范围" :disabled="locked" :options="[{value:'owned',label:'已拥有游戏'},{value:'recent',label:'最近游玩'}]"/><label class="check"><input v-model="steam.auto_sync_enabled" type="checkbox" :disabled="locked">每6小时自动同步</label></div><div class="homepage-savebar"><span>{{homeDirty?'有未保存的首页设置':'设置已保存'}}</span><button class="primary" :disabled="locked||!homeDirty||homeConflict">保存设置</button></div></form><section class="homepage-steam-status" aria-label="Steam 同步状态"><h2>同步状态</h2><dl><dt>API Key</dt><dd>{{steamStatus.api_key_configured?'已配置':'未配置'}}</dd><dt>上次同步</dt><dd>{{date(steamStatus.last_sync_at)}}</dd></dl><p v-if="steamStatus.last_error" class="homepage-feedback is-error">{{steamStatus.last_error}}</p><p class="homepage-help">{{dirty?'先保存或放弃当前修改，再开始同步。':!credentialsReady?'先填写并保存 ID64 和 API Key。':'同步后可在展示墙调整显示、排序和自选封面。'}}</p><button type="button" :disabled="locked||dirty||!credentialsReady" @click="syncSteam">{{busy==='sync'?'正在同步…':'立即同步'}}</button></section>
   </section>
  </template>
 </div>
</template>
